do $$ begin
  -- Pengaman: produksi selalu berisi pengguna nyata, jadi seed berhenti di sana.
  if exists (select 1 from public.profiles where nama_lengkap not like 'SIM %') then
    raise exception 'Database ini berisi pengguna nyata. Seed simulasi dibatalkan.'; end if;
end $$;

